select *
FROM jsh_supplier_manage
where 1=1


    and supplier_name like #{bindSupplierName}



    and credit_code like #{bindCreditCode}


    and date_format(entry_time,'%Y-%m-%d') >= #{beginTime}


    and date_format(entry_time,'%Y-%m-%d') <= #{endTime}


    and status = #{status}

and ifnull(delete_flag,'0') !='1'
order by create_time desc, id desc

